import java.awt.Color;
import java.util.HashMap;

/**
 * This class collects and provides some statistical data on the state 
 * of a field. It is flexible: it will create and maintain a counter 
 * for any class of object that is found within the field.
 *
 * @version 2016.02.29
 */
public class FieldStats
{
    // Counters for each type of entity (fox, rabbit, etc.) in the simulation.
    private HashMap<Class, Counter> counters;
    // Whether the counters are currently up to date.
    private boolean countsValid;

    /**
     * Construct a FieldStats object.
     */
    public FieldStats()
    {
        // Set up a collection for counters for each type of animal that
        // we might find
        counters = new HashMap<>();
        countsValid = true;
    }

    /**
     * Get details of what is in the field.
     * @return A string describing what is in the field.
     */
    public String getPopulationDetails(Field field)
    {
        StringBuffer buffer = new StringBuffer();
        if(!countsValid) {
            generateCounts(field);
        }
        for(Class key : counters.keySet()) {
            Counter info = counters.get(key);
            buffer.append(info.getName());
            buffer.append(": ");
            buffer.append(info.getCount());
            buffer.append(" ");
        }
        return buffer.toString();
    }

    /**
     * Invalidate the current set of statistics; reset all 
     * counts to zero.
     */
    public void reset()
    {
        countsValid = false;
        for(Class key : counters.keySet()) {
            Counter count = counters.get(key);
            count.reset();
        }
    }

    /**
     * Increment the count for one class of animal.
     * @param animalClass The class of animal to increment.
     */
    public void incrementCount(Class animalClass)
    {
        Counter count = counters.get(animalClass);
        if(count == null) {
            // We do not have a counter for this species yet.
            // Create one.
            count = new Counter(animalClass.getName());
            counters.put(animalClass, count);
        }
        count.increment();
    }

    /**
     * Indicate that an animal count has been completed.
     */
    public void countFinished()
    {
        countsValid = true;
    }

    /**
     * Determine whether the simulation is still viable.
     * I.e., should it continue to run.
     * @return true If there is more than one species alive.
     */
    public boolean isViable(Field field)
    {
        // How many counts are non-zero.
        int nonZero = 0;
        if(!countsValid) {
            generateCounts(field);
        }
        for(Class key : counters.keySet()) {
            Counter info = counters.get(key);
            if(info.getCount() > 0) {
                nonZero++;
            }
        }
        return nonZero > 1;
    }

    /**
     * Generate counts of the number of foxes and rabbits.
     * These are not kept up to date as foxes and rabbits
     * are placed in the field, but only when a request
     * is made for the information.
     * @param field The field to generate the stats for.
     */
    private void generateCounts(Field field)
    {
        reset();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object animal = field.getObjectAt(row, col);
                Plant plant = field.getPlantAt(row, col);
                if(animal != null) {
                    incrementCount(animal.getClass());
                }
                if(plant != null) {
                    incrementCount(plant.getClass());
                }
            }
        }
        countsValid = true;
    }
    public HashMap<Class, Counter> getCounters()
    {
        return counters;
    }
}
import java.awt.Color;

/**
 * Provide a counter for a participant in the simulation.
 * This includes an identifying string and a count of how
 * many participants of this type currently exist within 
 * the simulation.
 *
 * @version 2016.02.29
 */
public class Counter
{
    // A name for this type of simulation participant
    private String name;
    // How many of this type exist in the simulation.
    private int count;

    /**
     * Provide a name for one of the simulation types.
     * @param name  A name, e.g. "Fox".
     */
    public Counter(String name)
    {
        this.name = name;
        count = 0;
    }

    /**
     * @return The short description of this type.
     */
    public String getName()
    {
        return name;
    }

    /**
     * @return The current count for this type.
     */
    public int getCount()
    {
        return count;
    }

    /**
     * Increment the current count by one.
     */
    public void increment()
    {
        count++;
    }

    /**
     * Reset the current count to zero.
     */
    public void reset()
    {
        count = 0;
    }
}

import java.util.Random;
import java.util.List;
import java.awt.Color;
/**
 * A class responsible for generating the population,
 * as well as setting up the colours associated with each animal and plant class.
 *
 * @version 1.0
 */
public class PopulationGenerator
{

    /*///////////////////////////////////////////////////////////////
                                 CONSTANTS
    //////////////////////////////////////////////////////////////*/

    // The probability that an animal will be created in any given grid position.
    private static final double FOX_CREATION_PROBABILITY = 0.09;  
    private static final double REINDEER_CREATION_PROBABILITY = 0.11;
    private static final double SHEEP_CREATION_PROBABILITY = 0.11;
    private static final double BEAR_CREATION_PROBABILITY = 0.04;
    private static final double WOLVERINE_CREATION_PROBABILITY = 0.09;
    // The probability that a plant will be created in any given grid position.
    private static final double GRASS_SPAWN_PROBABILITY = 0.09;
    private static final double SAGE_SPAWN_PROBABILITY = 0.075;
    private static final double SEDGE_SPAWN_PROBABILITY = 0.07;
    // A constant for initial number of infections in the generated population.
    private static final int INITIAL_INFECTION_COUNT = 11;

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    private SimulatorView view;
    private AnimalFactoryProducer producer;
    private Field field;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Construct a population generator and set up the colours for representation of each animal class.
     */
    public PopulationGenerator(SimulatorView view, Field field)
    {
        this.view = view;
        this.field = field;
        producer = new AnimalFactoryProducer(field);
        setUpColors();
    }

    /**
     * The RGB colours associated with the given animals and plants passed to the constructor of Color class from awt library.
     */
    private void setUpColors()
    {
        view.setColor(CarnivoreFox.class, new Color(227, 93, 57));
        view.setColor(Grass.class, new Color(50, 184, 121));
        view.setColor(Sage.class, new Color(27, 117, 19));
        view.setColor(Reindeer.class, new Color(217, 162, 147));
        view.setColor(Sheep.class, Color.LIGHT_GRAY);
        view.setColor(Bear.class, new Color(112, 62, 49));
        view.setColor(Wolverine.class, Color.BLACK);
        view.setColor(Sedge.class, new Color(78, 117, 19));
        view.showColors();
    }

    /**
     * Populate the grid with animals and plants, infect the animals.
     * 
     * @param animals The list of Actor objects representing animals in the simulation
     * @param plants The list of Plant objects representing plants in the simulation
     */
    public void populate(List<Actor> animals , List<Actor> plants)
    {
      // Set up a randomizer, animal and plant factories
      Random rand = Randomizer.getRandom();
      field.clear();
      AnimalFactory herbivoreFactory = producer.getFactory(false);
      AnimalFactory carnivoreFactory = producer.getFactory(true);
      PlantFactory plantFactory = new PlantFactory(field);

      // Nested loop to go through every location on the grid and generate an animal of a certain class 
      // based on a comparison of randomised double with the creation probability of every animal
      for(int row = 0; row < field.getDepth(); row++) {
          for(int col = 0; col < field.getWidth(); col++) {
              Location location = new Location(row, col);
              if(rand.nextDouble() <= FOX_CREATION_PROBABILITY) {                  
                  animals.add(carnivoreFactory.getAnimal("FOX", location));
              }
              else if(rand.nextDouble() <= REINDEER_CREATION_PROBABILITY) {
                  animals.add(herbivoreFactory.getAnimal("SHEEP", location));
              }
              else if (rand.nextDouble() <= SHEEP_CREATION_PROBABILITY) {
                  animals.add(herbivoreFactory.getAnimal("REINDEER", location));
              }
              else if (rand.nextDouble() <= BEAR_CREATION_PROBABILITY) {
                  animals.add(carnivoreFactory.getAnimal("BEAR", location));
              }
              else if (rand.nextDouble() <= WOLVERINE_CREATION_PROBABILITY) {
                  animals.add(carnivoreFactory.getAnimal("WOLVERINE", location));
              }
                // else leave the location empty.
          }
      }

      // A loop to go through the list of generated animals and infect 11 animals
      for (int i = 0; i < INITIAL_INFECTION_COUNT; i++) {
          if (animals.get(i) instanceof Animal){
              Animal animal = (Animal) (animals.get(i));
              animal.setInfectionTimestamp(0);
          }    
      }

      // Nested loop to go through every location on the grid and generate a plant of a certain class 
      // based on a comparison of randomised double with the creation probability of every plant
      for(int row = 0; row < field.getDepth(); row++) {
          for(int col = 0; col < field.getWidth(); col++) {
              Location location = new Location(row, col);
              if(rand.nextDouble() <= GRASS_SPAWN_PROBABILITY) {                    
                  plants.add(plantFactory.getPlant("GRASS", location));
              }
              else if(rand.nextDouble() <= SAGE_SPAWN_PROBABILITY) {
                  plants.add(plantFactory.getPlant("SAGE", location));
              }
              else if(rand.nextDouble() <= SEDGE_SPAWN_PROBABILITY) {
                    plants.add(plantFactory.getPlant("SEDGE", location));
              }
                // else leave the location empty.
            }
        }
    } 
}

import java.util.TreeMap;
import java.util.List;
import java.util.ArrayList;
import java.util.Random;
/**
 * Class responsible for handling the simulation of the disease.
 *
 * @version 1.0
 */
public class DiseaseHandler
{

    /*///////////////////////////////////////////////////////////////
                                 CONSTANTS
    //////////////////////////////////////////////////////////////*/

    // cooldown before the animal achieves natural immunity
    private static final int DISINFECTION_DURATION = 5;
    private final Random rand = Randomizer.getRandom();
    private final Field field;

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    public static TreeMap<Integer, Integer> count;
    private int currentStep;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Creates a new disease handler
     * @param field The field to later get the animals per block and compute the density
     */
    public DiseaseHandler(Field field)
    {
        count = new TreeMap<>();
        this.field = field;
        currentStep = 0;
    }

    /*///////////////////////////////////////////////////////////////
                          DISEASE SIMULATION LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * Simulates the disease by iterating through every block in the field, and computing the density of the number of ppl infected 
     * in the given block to determine the likelyhood of being infected in the block
     */
    public void simulateDiseaseStep()
    {
        // fetch the animal per blocks eg : [block1 : [animal1,animal2, animal3]. block 2: [animal1, animal 2, animal3]...]
        List<List<Animal>> blocks = field.getAnimalsPerBlock();
        int infectionCount = 0;
        currentStep++;
        for (List<Animal> block : blocks) {
            int densityIndex = 0;
            List<Animal> uninfectedAnimals = new ArrayList<>();
            for(Animal animal : block) {
                if(animal.getInfectionTimestamp() != null && currentStep - animal.getInfectionTimestamp() < DISINFECTION_DURATION) {
                    // increase the counter of number of animals infected within this block.
                    densityIndex++;
                    continue;
                }
                if(animal.getInfectionTimestamp() == null) {
                    uninfectedAnimals.add(animal);
                }
            }
            // compute probability of being infected.
            double pValue = (double)((double)densityIndex/(double)block.size());
            for(Animal animal : uninfectedAnimals) {
                double randNumber = rand.nextDouble();
                if(randNumber < pValue ) {
                    animal.setInfectionTimestamp(currentStep);
                }
            }
            infectionCount += densityIndex;
        }
        count.put(currentStep, infectionCount);
    }
}
import java.util.Random;
/**
 * Responsible for mutating the weather of the simulation by randomly selecting a new weather(following a uniform distribution)
 * @version 1.0
 */
public class WeatherHandler
{

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    private Weather currentWeather;
    private int lastRecordedDay;
    private Random rand = Randomizer.getRandom();
    private SimulatorClock clock;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Creates a new Weather handler
     */
    public WeatherHandler(SimulatorClock clock)
    {
        currentWeather = getRandomWeather();
        lastRecordedDay = 1;
        this.clock = clock;
    }

    /**
     * Accessor Method for the current weathet
     * @return the current weather
     */
    public Weather getWeather()
    {
        return currentWeather;
    }

    /**
     * Randomly selects a new weather everyday
     */
    public void updateWeather()
    {
        if(lastRecordedDay != clock.getDayCount()) {
            currentWeather = getRandomWeather();
            lastRecordedDay = clock.getDayCount();
        }
    }

    /**
     *  Returns a random weather amongs the list of possible types of weather
     *  @return the randomly selected weather
     */
    private Weather getRandomWeather()
    {
        return Utils.getRandomEnumValue(Weather.class);
    }
}
/**
 * Simulates the behaviour of time by synchronizing itself with the current step of the simulation(linear formula: time = k * step)
 *
 * @version 1.0
 */
public class SimulatorClock
{

    /*///////////////////////////////////////////////////////////////
                                   STATE
    //////////////////////////////////////////////////////////////*/

    private final int INITIAL_TIME = 12;
    private final int TIME_FACTOR = 3;
    private final int STEPS_PER_DAY = 8;
    private int step;
    private int dayCount;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/    

    /**
     * Constructor for objects of class SimulatorClock.
     */
    public SimulatorClock()
    {
        step = 0;
    }

    /**
     * Returns a string indicating the time of the day in a human friendly format.
     * 
     * @return A string of the current time of the day in a Day:Hour:Minute format.
     */

    public String getStringTime()
    {
        String hourString = Utils.padLeft(String.valueOf(getHourOfDay()), 2);
        String minuteString = Utils.padRight(String.valueOf(getMinuteOfDay()), 2);
        return String.format("Day: %s | %s : %s ",getDayCount(),hourString, minuteString);
    }

    /*///////////////////////////////////////////////////////////////
                          TIME SIMULATION LOGIC
    //////////////////////////////////////////////////////////////*/

    /**
     * Acessor method for the current time(starts at mid day).
     * 
     * @return the current time.
     */
    public double getTime()
    {
        return (((double)(TIME_FACTOR) * step) + INITIAL_TIME) % 24;
    }

    /**
     * Accessor method for the current hour of the day.
     * 
     * @return the current hour (floored).
     */
    public int getHourOfDay()
    {
        return (int) getTime();
    }

    /**
     * The remainder of the current hours.
     * 
     * @return the minutes passed since the start of the last hour.
     */
    public int getMinuteOfDay()
    {
        return (int)((getTime() - (double)getHourOfDay()) * 100.0 * 0.6);
    }

    /**
     * Increments the internal steps of the clock.
     */
    public void incrementStep()
    {
        step++;
    }

    /**
     * Returns the number of days passed since the start of the simulation(starts at day 1).
     * 
     * @return the current day of the simulation.
     */
    public int getDayCount()
    {
        return ((int)((step + (INITIAL_TIME/TIME_FACTOR)) / STEPS_PER_DAY) + 1);
    }

    /**
     * Returns the current state of the day.
     * 
     * @returns the state of the day.
     */
    public DayState getDayState()
    {
        if(getTime() > 24 || getTime() < 6) {
            return DayState.NIGHT;
        } else {
            return DayState.DAYLIGHT;
        }
    }
}

/**
 * Shared behaviour between different animal factories
 *
 * @version 1.0
 */
public abstract class AnimalFactory
{

    protected Field field;

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Creates an AnimalFactory
     * @param reference to field to later pass in to animals
     */
    public AnimalFactory(Field field) 
    {
        this.field = field;
    }

    /**
     * Creates an Animal given an input animal type
     * @param animalType the type of the animal
     * @param location The base location of the newly created animal
     * @return the created animal
     */
    abstract Animal getAnimal(String animalType, Location location);
}
/**
 * Factory Class responsible for creating animals that are herbivore
 *
 * @version 1.0
 */
public class HerbivoreAnimalFactory extends AnimalFactory
{

    /*///////////////////////////////////////////////////////////////
                                CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

    /**
     * Creates A CarnivoreAnimalFactory.
     * 
     * @param field reference to later pass into animals
     */
    public HerbivoreAnimalFactory(Field field) {
        super(field);
    }

    /**
     * Creates and returns an animal given a particular type.
     * 
     * @param animalType The type of animal to create.
     * @param location The initial location of the newly created animal.
     * @return the newly created animal.
     */
    public Animal getAnimal(String animalType, Location location) {
        if(animalType == null) {
            return null;
        }
        Gender randomGender = Utils.getRandomEnumValue(Gender.class);
        if (animalType.equalsIgnoreCase("SHEEP")) {
            return new Sheep(true, field, location, randomGender);
        }
        else if (animalType.equalsIgnoreCase("REINDEER")) {
            return new Reindeer(true, field, location, randomGender);
        }
        return null;
    }
}
